# 整系数二次多项式因式分解工具

一款用 C++ 编写的整系数多项式因式分解程序，支持 `ax² + bx + c` 形式的整数系数多项式分解，自动处理符号化简与精度修正。

## 支持功能
- 提取三项公因子
- 平方差公式分解
- 完全平方公式分解
- 十字相乘法分解
- 自动修正浮点数开方误差
- 标准化输出格式

## 完整源码
```cpp
#include <iostream>
#include <string>
#include <cmath>
#include <cstdlib> // for llabs

using namespace std;

// 求两个数的最大公约数（绝对值）
long long gcd(long long a, long long b) {
    a = llabs(a);
    b = llabs(b);
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// 求三个数的最大公约数
long long gcd3(long long a, long long b, long long c) {
    return gcd(gcd(a, b), c);
}

// 判断完全平方数，是则返回平方根，否则返回-1
long long perfect_sqrt(long long n) {
    if (n < 0) return -1;
    if (n == 0) return 0;
    long long s = static_cast<long long>(sqrt(n));
    // 修正浮点数精度误差
    while (s * s > n) s--;
    while ((s + 1) * (s + 1) <= n) s++;
    return (s * s == n) ? s : -1;
}

// 格式化一次式 mx + n
string format_linear(long long m, long long n) {
    string res;
    if (m == 1) {
        res = "x";
    } else if (m == -1) {
        res = "-x";
    } else {
        res = to_string(m) + "x";
    }
    if (n > 0) {
        res += "+" + to_string(n);
    } else if (n < 0) {
        res += "-" + to_string(llabs(n));
    }
    return res;
}

// 格式化二次式 ax² + bx + c
string format_quadratic(long long a, long long b, long long c) {
    string res;
    // 二次项
    if (a == 1) {
        res = "x^2";
    } else if (a == -1) {
        res = "-x^2";
    } else {
        res = to_string(a) + "x^2";
    }
    // 一次项
    if (b != 0) {
        if (b == 1) {
            res += "+x";
        } else if (b == -1) {
            res += "-x";
        } else if (b > 0) {
            res += "+" + to_string(b) + "x";
        } else {
            res += to_string(b) + "x";
        }
    }
    // 常数项
    if (c != 0) {
        if (c > 0) {
            res += "+" + to_string(c);
        } else {
            res += to_string(c);
        }
    }
    return res;
}

// 核心因式分解函数：分解 ax² + bx + c
string factor(long long a, long long b, long long c) {
    // 常数情况
    if (a == 0 && b == 0) {
        return to_string(c);
    }

    // 一次式处理
    if (a == 0) {
        long long g = gcd(b, c);
        b /= g;
        c /= g;
        // 保证一次项系数为正
        if (b < 0) {
            b = -b;
            c = -c;
            g = -g;
        }
        string term = format_linear(b, c);
        if (g == 1) return term;
        else if (g == -1) return "-" + term;
        else return to_string(g) + "(" + term + ")";
    }

    // 二次式处理：第一步提取公因子
    long long g = gcd3(a, b, c);
    a /= g;
    b /= g;
    c /= g;

    // 保证二次项系数为正
    if (a < 0) {
        a = -a;
        b = -b;
        c = -c;
        g = -g;
    }

    string factor_part;

    // 情况1：常数项为0，提取x
    if (c == 0) {
        factor_part = "x(" + format_linear(a, b) + ")";
    }
    // 情况2：平方差公式 a² - b² = (a+b)(a-b)
    else if (b == 0 && c < 0) {
        long long sa = perfect_sqrt(a);
        long long sc = perfect_sqrt(-c);
        if (sa != -1 && sc != -1) {
            factor_part = "(" + format_linear(sa, sc) + ")(" + format_linear(sa, -sc) + ")";
        }
    }
    // 情况3：完全平方公式 (a±b)² = a²±2ab+b²
    if (factor_part.empty()) {
        long long delta = b * b - 4 * a * c;
        if (delta == 0) {
            long long sa = perfect_sqrt(a);
            long long sc = perfect_sqrt(c);
            if (sa != -1 && sc != -1) {
                long long mid = 2 * sa * sc;
                if ((b > 0 && mid == b) || (b < 0 && mid == -b)) {
                    long long sign = (b > 0) ? 1 : -1;
                    factor_part = "(" + format_linear(sa, sign * sc) + ")^2";
                }
            }
        }
    }
    // 情况4：十字相乘法
    if (factor_part.empty()) {
        bool found = false;
        long long a1, c1, a2, c2;
        long long abs_c = llabs(c);

        // 枚举二次项系数的所有正因数对
        for (long long i = 1; i <= a; i++) {
            if (a % i != 0) continue;
            a1 = i;
            a2 = a / i;

            // 枚举常数项的所有整数因数对
            for (long long j = -abs_c; j <= abs_c; j++) {
                if (j == 0) continue;
                if (c % j != 0) continue;
                c1 = j;
                c2 = c / j;

                if (a1 * c2 + a2 * c1 == b) {
                    found = true;
                    break;
                }
            }
            if (found) break;
        }

        if (found) {
            factor_part = "(" + format_linear(a1, c1) + ")(" + format_linear(a2, c2) + ")";
        }
    }

    // 无法分解则返回原式
    if (factor_part.empty()) {
        factor_part = format_quadratic(a, b, c);
    }

    // 组合公因子
    if (g == 1) return factor_part;
    else if (g == -1) return "-" + factor_part;
    else return to_string(g) + factor_part;
}

int main() {
    cout << "===== 整系数多项式因式分解程序 =====" << endl;
    cout << "分解形式：ax² + bx + c（整数系数）" << endl;
    cout << "支持：提取公因式、平方差、完全平方、十字相乘法" << endl;
    cout << "输入格式：a b c（空格分隔），输入 0 0 0 退出" << endl << endl;

    long long a, b, c;
    while (true) {
        cout << "请输入系数 a b c: ";
        cin >> a >> b >> c;
        if (a == 0 && b == 0 && c == 0) {
            cout << "程序已退出。" << endl;
            break;
        }
        cout << "分解结果: " << factor(a, b, c) << endl << endl;
    }
    return 0;
}
```

## 使用说明
1. 编译运行后，按提示输入三个整数 `a b c`，空格分隔
2. 程序自动输出因式分解结果
3. 输入 `0 0 0` 退出程序
4. 支持一次式、二次式、常数多种形式的自动识别分解
